// src/routes/ListDetail.jsx
import React, { useState } from "react";
import { useParams } from 'react';
import shoppingLists from "../data/shoppingListData";
import ShoppingItem from "../components/ShoppingItem";
import MemberList from "../components/MemberList";
import BackButton from "../components/BackButton";

export default function ListDetail() {
  const { id } = useParams();
  const list = shoppingLists.find((l) => l.id === parseInt(id));
  const [items, setItems] = useState(list.items);

  const toggleItem = (itemId) => {
    setItems((prev) =>
      prev.map((item) =>
        item.id === itemId ? { ...item, done: !item.done } : item
      )
    );
  };

  const addItem = () => {
    const name = prompt("Enter new item:");
    if (name)
      setItems((prev) => [
        ...prev,
        { id: Date.now(), name, done: false },
      ]);
  };

  const removeItem = (id) => {
    setItems((prev) => prev.filter((item) => item.id !== id));
  };

  return (
    <div style={{ padding: "20px" }}>
      <BackButton />
      <h2>{list.name}</h2>

      <h3>🛍 Items</h3>
      {items.map((item) => (
        <ShoppingItem
          key={item.id}
          item={item}
          onToggle={() => toggleItem(item.id)}
          onRemove={() => removeItem(item.id)}
        />
      ))}

      <button onClick={addItem} style={{ marginTop: "10px" }}>
        ➕ Add Item
      </button>

      <h3 style={{ marginTop: "30px" }}>👥 Members</h3>
      <MemberList members={list.members} />
    </div>
  );
}
